 res[i]={'mathdb_id':id,'title':r['title'],'literal_statement':r['statement'],'provenance':provenance,'source':source,'recommended_disposition':disp,'review_depth':depth,'mathematical_attempt_and_coverage':coverage,'remaining_gaps_or_exclusion_bridge':gaps,'lean_cost':cost,'lean_endpoint':None,'proposed_discovery':False,'accepted_credit':0,'root_decision':None,'historical_screen':'Required campaign ledgers and inherited family restrictions read; ID search of existing SUMMARY.md/results.json/ledger files found only current-ledger launch note. See history-files.txt. This is not global historical or novelty clearance.','registry_screen':'Current HEAD receipts and current D5/Problems path inventories in sources; path screening is not proof-body clearance. No surviving candidate claimed novelty.'}
